TLM.f("Tempora/Quad1-1",{"officium":"Feria Secunda infra Hebdomadam I in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super populum"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad1-0","sections":{"Introitus":[{"k":"ref","la":"Ps 122:2"},{"k":"text","la":"Sicut óculi servórum in mánibus dominórum suórum: ita óculi nostri ad Dóminum, Deum nostrum, donec misereátur nobis: miserére nobis, Dómine, miserére nobis."},{"k":"ref","la":"Ps 122:1"},{"k":"text","la":"Ad te levávi óculos meos: qui hábitas in cœlis,"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sicut óculi servórum in mánibus dominórum suórum: ita óculi nostri ad Dóminum, Deum nostrum, donec misereátur nobis: miserére nobis, Dómine, miserére nobis."}],"Oratio":[{"k":"text","la":"Convérte nos, Deus, salutáris noster: et, ut nobis jejúnium quadragesimále profíciat, mentes nostras cœléstibus ínstrue disciplínis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Ezechiélis Prophétæ"},{"k":"ref","la":"Ezech 34:11-16"},{"k":"text","la":"Hæc dicit Dóminus Deus: Ecce, ego ipse requíram oves meas, et visitábo eas. Sicut vísitat pastor gregem suum in die, quando fúerit in médio óvium suárum dissipatárum: sic visitábo oves meas, et liberábo eas de ómnibus locis, in quibus dispérsæ fúerant in die nubis et calíginis. Et edúcam eas de pópulis, et congregábo eas de terris, et indúcam eas in terram suam: et pascam eas in móntibus Israël, in rivis, et in cunctis sédibus terræ. In páscuis ubérrimis pascam eas, et in móntibus excélsis Israël erunt páscua eárum: ibi requiéscent in herbis viréntibus, et in páscuis pínguibus pascéntur super montes Israël. Ego pascam oves meas, et ego eas accubáre fáciam, dicit Dóminus Deus. Quod períerat, requíram; et quod abjéctum erat, redúcam; et quod confractum fúerat, alligábo; et quod infírmum fúerat, consolidábo; et quod pingue et forte, custódiam: et pascam illas in judício, dicit Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 83:10; 83:9"},{"k":"text","la":"Protéctor noster, áspice, Deus, et réspice super servos tuos."},{"k":"text","la":"Dómine, Deus virtútum, exáudi preces servórum tuórum.","mark":"V"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Matthǽum"},{"k":"ref","la":"Matt 25:31-46"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum vénerit Fílius hóminis in majestáte sua, et omnes Angeli cum eo, tunc sedébit super sedem majestátis suæ: et congregabúntur ante eum omnes gentes, et separábit eos ab ínvicem, sicut pastor ségregat oves ab hædis: et státuet oves quidem a dextris suis, hædos autem a sinístris. Tunc dicet Rex his, qui a dextris ejus erunt: Veníte, benedícti Patris mei, possidéte parátum vobis regnum a constitutióne mundi. Esurívi enim, et dedístis mihi manducáre; sitívi, et dedístis mihi bíbere; hospes eram, et collegístis me; nudus, et cooperuístis me; infírmus, et visitástis me; in cárcere eram, et venístis ad me. Tunc respondébunt ei justi, dicéntes: Dómine, quando te vídimus esuriéntem, et pávimus te; sitiéntem, et dedimus tibi potum? quando autem te vídimus hóspitem, et collégimus te? aut nudum, et cooperúimus te? aut quando te vídimus infírmum, aut in cárcere, et vénimus ad te? Et respóndens Rex, dicet illis: Amen, dico vobis: quámdiu fecístis uni ex his frátribus meis mínimis, mihi fecístis. Tunc dicet et his, qui a sinístris erunt: Discédite a me, maledícti, in ignem ætérnum, qui parátus est diábolo et ángelis ejus. Esurívi enim, et non dedístis mihi manducáre; sitívi, et non dedístis mihi potum; hospes eram, et non collegístis me; nudus, et non cooperuístis me; infírmus et in cárcere, et non visitástis me. Tunc respondébunt ei et ipsi, dicéntes: Dómine, quando te vídimus esuriéntem, aut sitiéntem, aut hóspitem, aut nudum, aut infírmum, aut in cárcere, et non ministrávimus tibi? Tunc respondébit illis, dicens: Amen, dico vobis: Quámdiu non fecístis uni de minóribus his, nec mihi fecístis. Et ibunt hi in supplícium ætérnum: justi autem in vitam ætérnam."}],"Offertorium":[{"k":"ref","la":"Ps 118:18; 118:26; 118:73"},{"k":"text","la":"Levábo óculos meos, et considerábo mirabília tua, Dómine, ut dóceas me justítias tuas: da mihi intelléctum, et discam mandáta tua."}],"Secreta":[{"k":"text","la":"Múnera tibi, Dómine, obláta sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:40; 25:34"},{"k":"text","la":"Amen, dico vobis: quod uni ex mínimis meis fecístis, mihi fecístis: veníte, benedícti Patris mei, possidéte parátum vobis regnum ab inítio sǽculi."}],"Postcommunio":[{"k":"text","la":"Salutáris tui, Dómine, múnere satiáti, súpplices exorámus: ut, cujus lætámur gustu, renovémur efféctu."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Absólve, quǽsumus, Dómine, nostrórum víncula peccatórum: et, quidquid pro eis merémur, propitiátus avérte."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7f5109e55cfeddb8":{"t":"Ps 122, 2, Ps 122, 1\n(Ps 122, 2) Kao što su oči slugu uprte u ruke gospodara njihovih, tako su naše oči uprte u Gospodina Boga našega dok nam se ne smiluje. Smiluj nam se Gospodine, smiluj nam se! (Ps 122, 1) Podižem oči svoje k tebi koji stanuješ na nebesima.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 122, 2) Kao što su oči slugu uprte u ruke gospodara njihovih, tako su naše oči uprte u Gospodina Boga našega dok nam se ne smiluje. Smiluj nam se Gospodine, smiluj nam se!"},"3fafb23647ddd539":{"t":"<i>Pomolimo se</i>.\nObrati nas, Bože, spasitelju naš, i da nam bude od koristi korizmeni post, pouči naše duše nebeskim naukama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"798195e123858b9c":{"t":"Ez 34, 11-16\nČitanje Ezekiela proroka. Ovo govori Gospodin Bog: Evo, ja ću sam potraži svoje ovce i pohoditi ih. Kao što pastir obilazi svoje stado, kad je kraj svojih razbježalih ovaca, tako ću i ja bdjeti nad svojim ovcama i udaljit ću ih od mjesta, kuda su se bile razbježale za oblačnih i maglovitih dana. Izvest ću ih iz stranih naroda, skupit ću ih iz svih krajeva zemlje i uvesti ih u njihovu zemlju i pustit ću ih da pasu po izraelskim gorama, pokraj potoka po svim naseljima. Dat ću da pasu na dobrim pašnjacima, a pašnjaci će im biti na izraelskim gorama, tu će plandovati po zelenoj travi i pasti na dobrim pašnjacima izraelskih gora. Ja ću pasti svoje ovce i pustit ću ih da se odmaraju, govori Gospodin Bog. Tražit ću zalutale, privesti rastjerane, privezati slomljene, okrijepiti slabe, čuvat ću debele i jake, sve ću pasti po pravdi, govori Gospodin svemogući."},"7fd329164d15c2a5":{"t":"Ps 83, 10 i 9\nBranitelju naš, pogledaj, Bože, i vidi sluge svoje. Gospodine Bože vojska, čuj molitve slugu svojih.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega."},"b7b9e43349ffba4f":{"t":"Mt 25, 31-46\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kad Sin čovječji dođe sa svim anđelima u svojem sjaju, sjest će na prijestolje svoga veličanstva, i pred njim će se skupiti svi narodi, koje će on razlučiti jedne od drugih, kao što pastir luči ovce od jaraca. Ovce će postaviti sebi s desne, a jarce s lijeve strane. Tada će kralj reći onima s desne strane: Dođite, blagoslovljeni Oca mojega, uđite u kraljevstvo koje vam je pripravljeno od postanka svijeta. Bio sam gladan i nahranili ste me, žedan i napojili ste me, putnik i primili ste me, gol i odjenuli ste me, bolestan i posjetili ste me, u tamnici i došli ste k meni. A pravednici će tada pitati: Gospodine, kad smo te vidjeli gladna i dali ti jesti, žedna i dali ti piti? Kad smo te vidjeli kao putnika i primili te, gola i obukli te. Kad smo te vidjeli bolesna ili u tamnici i posjetili te? I kralj će im odgovoriti: Zaista vam kažem, što ste god učinili jednome od moje najmanje braće, meni ste učinili! Tada će reći onima s lijeve strane: Odlazite od mene, prokleti, u vječni oganj koji je pripravljen đavlu i njegovim anđelima. Bio sam gladan i niste me nahranili, žedan i niste me napojili, putnik i niste me primili, gol i niste me obukli, bolestan i u tamnici i niste me posjetili. Tada će ga i oni upitati: Gospodine, kad smo te vidjeli gladna, ili žedna, ili putnika, ili bolesna, ili u tamnici i nismo ti pritekli u pomoć? A on će im reći: Zaista vam kažem, što niste učinili nekom od ovih najmanjih, meni niste učinili. I ovi će otići u vječne muke, a pravednici u vječni život."},"a0e7a7fb958898bb":{"t":"Ps 118, 18 i 26 i 73\nDižem oči svoje i promatram divna djela tvoja, Gospodine. Nauči me kako ću upoznati tvoju pravdu, daj mi razum da pravo shvatim zakone tvoje."},"f5e028ee08e03819":{"t":"Posveti, Gospodine, darove tebi prikazane i očisti nas od ljaga naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"1ae8170596eb3c38":{"t":"Mt 25, 40 i 34\nZaista vam kažem, što ste god učinili jednome od moje najmanje braće meni ste učinili. Dođite, blagoslovljeni Oca mojega, uđite u kraljevstvo koje vam je pripravljeno od postanka svijeta."},"5df89afb39d67e8c":{"t":"<i>Pomolimo se</i>.\nNahranjeni tvojim spasonosnim darom, ponizno te molimo, da nas obnovi djelovanje onog otajstva koje radosno primamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"12203fd96cc375e8":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nOdriješi, molimo, Gospodine, veze naših grijeha i milostivo odvrati sve što za njih zaslužujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
